def get_logo(app_name: str) -> dict:
    """Récupère le logo d'une application."""
    return APP_LOGOS.get(app_name.lower().replace(" ", "_").replace("-", "_"), {})


def get_all_logos() -> dict:
    """Retourne tous les logos disponibles avec SVG."""
    return {k: {"name": v["name"], "color": v["color"], "svg": v["svg"]} for k, v in APP_LOGOS.items()}


def get_svg(app_name: str) -> str:
    """Retourne le SVG d'un logo."""
    logo = get_logo(app_name)
    return logo.get("svg", "")
